namespace nb {
static std::string label_or_func(const Analysis& a, u32 off) {
    char b[32]; snprintf(b, sizeof b, "Func_%02X_%04X", Analysis::bank_of(off), Analysis::addr_of(off));
    return b;
}

static const char* GEN_HEADER =
    "// GENERATED by NativeBoy Studio static recompiler (SM83 -> C++). Edits are overwritten on rebuild.\n"
    "#include \"nb_gen.h\"\n";

struct EmitCtx {
    std::function<bool(u16)> is_local;
    bool ram_mode = false;
};

static std::string L(u16 a) { return "L" + hex4(a); }
static std::string H(unsigned v) { char b[16]; snprintf(b, sizeof b, "0x%04X", v & 0xFFFF); return b; }

static std::string jump_to(const EmitCtx& c, u16 t) {
    if (c.is_local(t)) return "CHK(" + H(t) + ") goto " + L(t) + ";";
    return "LEAVE(" + H(t) + ")";
}

// Emits one instruction. 'fall' = address of the instruction emitted right after (or -1).
static void emit_instr(std::ostringstream& o, const EmitCtx& c, u16 addr, const u8* b, int fall, const std::string& hook) {
    u8 op = b[0];
    const OpInfo& oi = op_info(op);
    int len = op == 0xCB ? 2 : oi.len;
    u16 next = (u16)(addr + len);
    o << L(addr) << ": {";
    if (op == 0xCB) o << " // " << cb_info(b[1]).mnem << "\n";
    else o << " // " << oi.mnem << "\n";
    if (!hook.empty()) o << "  if (" << hook << "(m)) return true;\n";
    if (c.ram_mode) {   // RAM code may have been rewritten: verify the bytes we compiled
        o << "  if (";
        for (int i = 0; i < len; i++) o << (i ? " || " : "") << "rd(m, " << H(addr + i) << ") != 0x" << hex2(b[i]);
        o << ") LEAVE(" << H(addr) << ")\n";
    }
    if (op != 0xCB) {
        if (len == 2) o << "  const u8 n8 = 0x" << hex2(b[1]) << "; const s8 e8 = (s8)n8; (void)n8; (void)e8;\n";
        if (len == 3) o << "  const u16 n16 = 0x" << hex4(b[1] | (b[2] << 8)) << "; (void)n16;\n";
    }
    auto flow_next = [&]() {
        o << "  CHK(" << H(next) << ")";
        if (fall == next && c.is_local(next)) o << "\n";
        else if (c.is_local(next)) o << " goto " << L(next) << ";\n";
        else o << " LEAVE(" << H(next) << ")\n";
    };
    switch (oi.kind) {
    case OK_NORMAL:
        if (op == 0xCB) {
            const OpInfo& q = cb_info(b[1]);
            o << "  " << (q.pre ? "m.tick(" + std::to_string(q.pre) + "); " : std::string()) << q.code << " m.tick(" << q.post << ");\n";
        } else {
            o << "  " << (oi.pre ? "m.tick(" + std::to_string(oi.pre) + "); " : std::string()) << oi.code << " m.tick(" << oi.post << ");\n";
        }
        flow_next();
        break;
    case OK_EI: case OK_DI:
        o << "  " << oi.code << " m.tick(4);\n";
        flow_next();
        break;
    case OK_STOP:
        o << "  " << oi.code << " m.tick(4); LEAVE(" << H(next) << ")\n";
        break;
    case OK_JP:
        o << "  m.tick(" << oi.cycles << "); " << jump_to(c, (u16)(b[1] | (b[2] << 8))) << "\n";
        break;
    case OK_JR: {
        u16 t = (u16)(addr + 2 + (s8)b[1]);
        o << "  m.tick(" << oi.cycles << "); " << jump_to(c, t) << "\n";
        break;
    }
    case OK_JP_CC: case OK_JR_CC: {
        u16 t = oi.kind == OK_JP_CC ? (u16)(b[1] | (b[2] << 8)) : (u16)(addr + 2 + (s8)b[1]);
        o << "  if (" << oi.cond << ") { m.tick(" << oi.cycles_taken << "); " << jump_to(c, t) << " }\n";
        o << "  m.tick(" << oi.cycles << ");\n";
        flow_next();
        break;
    }
    case OK_CALL:
        o << "  push16(m, " << H(next) << "); m.tick(" << oi.cycles << "); " << jump_to(c, (u16)(b[1] | (b[2] << 8))) << "\n";
        break;
    case OK_CALL_CC:
        o << "  if (" << oi.cond << ") { push16(m, " << H(next) << "); m.tick(" << oi.cycles_taken << "); " << jump_to(c, (u16)(b[1] | (b[2] << 8))) << " }\n";
        o << "  m.tick(" << oi.cycles << ");\n";
        flow_next();
        break;
    case OK_RET:
        o << "  m.pc = pop16(m); m.tick(" << oi.cycles << "); return true;\n";
        break;
    case OK_RET_CC:
        o << "  if (" << oi.cond << ") { m.pc = pop16(m); m.tick(" << oi.cycles_taken << "); return true; }\n";
        o << "  m.tick(" << oi.cycles << ");\n";
        flow_next();
        break;
    case OK_RETI:
        o << "  m.pc = pop16(m); m.ime = true; m.ei_delay = 0; m.next_event = 0; m.tick(" << oi.cycles << "); return true;\n";
        break;
    case OK_RST:
        o << "  push16(m, " << H(next) << "); m.tick(" << oi.cycles << "); " << jump_to(c, (u16)oi.rst) << "\n";
        break;
    case OK_JP_HL:
        o << "  m.pc = HL; m.tick(4); return true;\n";
        break;
    case OK_HALT:
        o << "  m.pc = " << H(next) << "; if (m.ime || !(m.ie & m.iflag & 0x1F)) m.halted = true; else m.halt_bug = true; m.tick(4); return true;\n";
        break;
    case OK_ILLEGAL:
        o << "  m.pc = " << H(addr) << "; return false; // illegal opcode: handled by the interpreter (CPU lock)\n";
        break;
    }
    o << "}\n";
}

static bool write_file(const std::string& path, const std::string& data, std::string& err) {
    std::ofstream f(std::filesystem::u8path(path), std::ios::binary);
    if (!f) { err = "Não foi possível gravar " + path; return false; }
    f.write(data.data(), (std::streamsize)data.size());
    return (bool)f;
}

bool generate_cpp(const Analysis& a, const std::string& out, const CodegenOptions& opt, CodegenResult& res, std::string& err) {
    res = CodegenResult();
    size_t n = a.rom.size();
    int nbanks = (int)(n / 0x4000);
    std::map<u32, std::string> hookmap;
    for (auto& h : opt.hooks) hookmap[h.off] = h.func;

    // nb_gen.h
    {
        std::ostringstream o;
        o << "#pragma once\n#include \"gb.h\"\n#include \"cpu_ops.h\"\nusing namespace gb;\n"
             "#define CHK(nx) if (GB_UNLIKELY(m.ev)) { m.pc = (u16)(nx); return true; }\n"
             "#define LEAVE(nx) { m.pc = (u16)(nx); return true; }\n";
        for (auto& h : opt.hooks) o << "bool " << h.func << "(gb::Machine& m);\n";
        if (!write_file(out + "/nb_gen.h", o.str(), err)) return false;
    }

    std::vector<std::string> page_fn((size_t)nbanks * 16);
    for (int bank = 0; bank < nbanks; bank++) {
        std::ostringstream o;
        o << GEN_HEADER;
        o << "// ROM bank " << bank << "\n";
        bool any = false;
        for (int page = 0; page < 16; page++) {
            u32 base = (u32)bank * 0x4000 + page * 0x400;
            std::vector<u32> ins;
            for (u32 off = base; off < base + 0x400 && off < n; off++) if (a.fl[off] & AF_START) ins.push_back(off);
            if (ins.empty()) continue;
            any = true;
            char fname[32]; snprintf(fname, sizeof fname, "P_%02X_%X", bank, page);
            page_fn[(size_t)bank * 16 + page] = fname;
            res.n_pages++;
            u16 region_lo = bank == 0 ? 0x0000 : 0x4000;
            std::vector<u8> local(0x400, 0);
            for (u32 off : ins) local[off - base] = 1;
            EmitCtx c;
            c.is_local = [&](u16 t) -> bool {
                if (t < region_lo || t >= region_lo + 0x4000) return false;
                u32 to = Analysis::off_of(bank, t);
                if (bank == 0 && t >= 0x4000) return false;
                return to >= base && to < base + 0x400 && local[to - base];
            };
            o << "\nbool " << fname << "(Machine& m) {\n  switch (m.pc) {\n";
            for (u32 off : ins) { u16 ad = Analysis::addr_of(off); o << "  case " << H(ad) << ": goto " << L(ad) << ";\n"; }
            o << "  default: return false;\n  }\n";
            for (size_t k = 0; k < ins.size(); k++) {
                u32 off = ins[k];
                u16 ad = Analysis::addr_of(off);
                int fall = k + 1 < ins.size() ? Analysis::addr_of(ins[k + 1]) : -1;
                u8 bytes[3] = {a.rom[off], off + 1 < n ? a.rom[off + 1] : (u8)0, off + 2 < n ? a.rom[off + 2] : (u8)0};
                auto hk = hookmap.find(off);
                if (a.fl[off] & (AF_CALL | AF_ENTRY)) {   // readable function names in the generated C++
                    auto sy = a.sym.rom.find(off);
                    o << "  // ---- " << (sy != a.sym.rom.end() ? sy->second : label_or_func(a, off)) << " ----\n";
                }
                emit_instr(o, c, ad, bytes, fall, hk == hookmap.end() ? std::string() : hk->second);
                res.n_instr++;
            }
            o << "}\n";
        }
        if (!any) continue;
        char fn[32]; snprintf(fn, sizeof fn, "bank_%02X.cpp", bank);
        if (!write_file(out + "/" + fn, o.str(), err)) return false;
        res.files.push_back(fn);
    }

    // RAM snippets (code the game copies to RAM, e.g. the OAM DMA routine). Every
    // instruction re-checks its own bytes, so rewritten RAM code falls back safely.
    std::map<u16, std::vector<std::string>> ram_entries;
    {
        std::ostringstream o;
        o << GEN_HEADER;
        int si = 0;
        for (auto& sn : a.ram_code) {
            std::vector<u16> ins = sn.starts;
            if (ins.empty()) continue;
            char fname[32]; snprintf(fname, sizeof fname, "R_%04X_%d", sn.addr, si++);
            res.n_ram_snippets++;
            EmitCtx c; c.ram_mode = true;
            std::set<u16> local(ins.begin(), ins.end());
            c.is_local = [&](u16 t) { return local.count(t) > 0; };
            o << "\nbool " << fname << "(Machine& m) {\n  switch (m.pc) {\n";
            for (u16 ad : ins) {
                size_t rel = ad - sn.addr;
                int len = sn.bytes[rel] == 0xCB ? 2 : op_info(sn.bytes[rel]).len;
                o << "  case " << H(ad) << ": if (";
                for (int i = 0; i < len; i++) o << (i ? " || " : "") << "rd(m, " << H(ad + i) << ") != 0x" << hex2(sn.bytes[rel + i]);
                o << ") return false; goto " << L(ad) << ";\n";
            }
            o << "  default: return false;\n  }\n";
            for (size_t k = 0; k < ins.size(); k++) {
                u16 ad = ins[k];
                size_t rel = ad - sn.addr;
                u8 bytes[3] = {sn.bytes[rel], rel + 1 < sn.bytes.size() ? sn.bytes[rel + 1] : (u8)0, rel + 2 < sn.bytes.size() ? sn.bytes[rel + 2] : (u8)0};
                int fall = k + 1 < ins.size() ? ins[k + 1] : -1;
                emit_instr(o, c, ad, bytes, fall, "");
                ram_entries[ad].push_back(fname);
                res.n_ram_instr++;
            }
            o << "}\n";
        }
        if (!write_file(out + "/ram_code.cpp", o.str(), err)) return false;
        res.files.push_back("ram_code.cpp");
    }

    // dispatch tables + metadata
    {
        std::ostringstream o;
        o << GEN_HEADER;
        o << "#include <cstring>\n";
        for (auto& f : page_fn) if (!f.empty()) o << "bool " << f << "(Machine&);\n";
        std::set<std::string> rdecl;
        for (auto& e : ram_entries) for (auto& fn : e.second) if (rdecl.insert(fn).second) o << "bool " << fn << "(Machine&);\n";
        o << "\nstatic const NativeFn g_pages[" << (nbanks * 16) << "] = {\n";
        for (size_t i = 0; i < page_fn.size(); i++) o << "  " << (page_fn[i].empty() ? "nullptr" : page_fn[i]) << ",\n";
        o << "};\n";
        // multi-variant RAM dispatchers
        std::vector<std::pair<u16, std::string>> ram_tab;
        for (auto& e : ram_entries) {
            if (e.second.size() == 1) { ram_tab.push_back({e.first, e.second[0]}); continue; }
            std::string dn = "RV_" + hex4(e.first);
            o << "static bool " << dn << "(Machine& m) {";
            for (auto& fn : e.second) o << " if (" << fn << "(m)) return true;";
            o << " return false; }\n";
            ram_tab.push_back({e.first, dn});
        }
        o << "static const struct { u16 pc; NativeFn fn; } g_ram[] = {\n";
        for (auto& e : ram_tab) o << "  {" << H(e.first) << ", " << e.second << "},\n";
        o << "  {0, nullptr}\n};\n";
        o << "struct GameResolver : NativeResolver {\n"
             "  NativeFn ram[0x8000];\n"
             "  GameResolver() { memset(ram, 0, sizeof ram); for (int i = 0; g_ram[i].fn; i++) ram[g_ram[i].pc - 0x8000] = g_ram[i].fn; }\n"
             "  NativeFn find(int bank, u16 pc) override {\n"
             "    if (bank < 0) return pc >= 0x8000 ? ram[pc - 0x8000] : nullptr;\n"
             "    if (pc < 0x4000) return bank == 0 ? g_pages[pc >> 10] : nullptr;\n"
             "    if (bank == 0 || bank >= " << nbanks << ") return nullptr;\n"
             "    return g_pages[bank * 16 + ((pc & 0x3FFF) >> 10)];\n"
             "  }\n};\n"
             "NativeResolver* nb_game_resolver() { static GameResolver r; return &r; }\n";
        std::string safe;
        for (char ch : opt.game_name) safe += (ch == '"' || ch == '\\') ? '_' : ch;
        o << "const char* nb_game_name() { return \"" << safe << "\"; }\n";
        o << "int nb_game_native_instr() { return " << res.n_instr << "; }\n";
        o << "int nb_game_ram_instr() { return " << res.n_ram_instr << "; }\n";
        o << "bool nb_game_sgb() { return " << (opt.sgb ? "true" : "false") << "; }\n";
        o << "extern \"C\" const unsigned char nb_rom_data[];\nextern \"C\" const unsigned int nb_rom_size;\n";
        o << "const unsigned char* nb_game_rom(unsigned* size) { *size = nb_rom_size; return nb_rom_data; }\n";
        if (!opt.hooks_file) o << "void nb_user_frame(gb::Machine&) {}\nvoid nb_user_init(gb::Machine&) {}\n";
        if (!write_file(out + "/game_table.cpp", o.str(), err)) return false;
        res.files.push_back("game_table.cpp");
    }
    // embedded ROM data (the game's resources): no external ROM file needed at run time
    {
        std::string rom(a.rom.begin(), a.rom.end());
        if (!write_file(out + "/rom.bin", rom, err)) return false;
        std::ostringstream o;
        o << "    .section .rodata\n    .balign 16\n    .globl nb_rom_data\nnb_rom_data:\n    .incbin \"rom.bin\"\n"
             "    .balign 4\n    .globl nb_rom_size\nnb_rom_size:\n    .long " << a.rom.size() << "\n"
             "#if defined(__ELF__) && defined(__arm__)\n    .section .note.GNU-stack,\"\",%progbits\n#elif defined(__ELF__)\n    .section .note.GNU-stack,\"\",@progbits\n#endif\n";
        if (!write_file(out + "/rom_data.S", o.str(), err)) return false;
        res.files.push_back("rom_data.S");
    }
    return true;
}

} // namespace nb
